-- esp.lua — Highlight-based player outline. Local instances never replicate.
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Util = __require("util")

local ESP = {}

local container
local tracked = {}
local connection
local fill = Color3.fromRGB(120, 180, 255)

local function getContainer()
	if container and container.Parent then
		return container
	end

	local folder = Instance.new("Folder")
	folder.Name = "OJB_ESP"

	-- CoreGui survives ScreenGui cleanup by the game and is never replicated.
	local ok = pcall(function()
		folder.Parent = CoreGui
	end)
	if not ok or not folder.Parent then
		local camera = workspace.CurrentCamera
		if camera then
			folder.Parent = camera
		end
	end

	container = folder
	return container
end

local function isTarget(player)
	return player ~= Players.LocalPlayer and player.Character ~= nil
end

local function attach(player)
	if not isTarget(player) then
		return
	end

	local character = player.Character
	if not character or not character:FindFirstChildOfClass("Humanoid") then
		return
	end

	local highlight = tracked[player]
	if highlight and highlight.Parent then
		highlight.Adornee = character
		return
	end

	highlight = Instance.new("Highlight")
	highlight.Name = "OJB_ESP_" .. player.Name
	highlight.Adornee = character
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.FillColor = fill
	highlight.FillTransparency = 0.55
	highlight.OutlineColor = fill
	highlight.OutlineTransparency = 0
	highlight.Parent = getContainer()

	tracked[player] = highlight
end

local function detach(player)
	local highlight = tracked[player]
	if highlight then
		highlight:Destroy()
		tracked[player] = nil
	end
end

local function clearAll()
	for player in pairs(tracked) do
		detach(player)
	end
	table.clear(tracked)
end

local function sweep()
	for _, player in ipairs(Players:GetPlayers()) do
		attach(player)
	end
end

function ESP.setEnabled(enabled)
	if not enabled then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		clearAll()
		return true
	end

	sweep()

	for _, player in ipairs(Players:GetPlayers()) do
		local character = player.Character
		if character then
			character.ChildAdded:Connect(function()
				if connection then
					attach(player)
				end
			end)
		end
	end

	if not connection then
		connection = RunService.Heartbeat:Connect(function()
			sweep()
			-- Drop entries for players who left or lost their character.
			for player, highlight in pairs(tracked) do
				if not player.Parent or not player.Character then
					detach(player)
				elseif highlight.Adornee ~= player.Character then
					highlight.Adornee = player.Character
				end
			end
		end)
	end
	return true
end

function ESP.setColor(color)
	fill = color
	for _, highlight in pairs(tracked) do
		if highlight.Parent then
			highlight.FillColor = color
			highlight.OutlineColor = color
		end
	end
	return true
end

function ESP.bind()
	Players.PlayerAdded:Connect(function(player)
		if connection then
			player.CharacterAdded:Connect(function()
				if connection then
					task.wait(0.3)
					attach(player)
				end
			end)
		end
	end)
	Players.PlayerRemoving:Connect(detach)
end

function ESP.destroy()
	ESP.setEnabled(false)
	if container then
		container:Destroy()
		container = nil
	end
end

return ESP
end
__modules["features/teleport"] = function()
-- teleport.lua — saved waypoints and player-to-player movement.
local Players = game:GetService("Players")

local Util = __require("util")

local Teleport = {}

local waypoints = {}

function Teleport.saveWaypoint(name)
	name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if name == "" then
		return false, "empty name"
	end

	local camera = workspace.CurrentCamera
	if not camera then
		return false, "no camera"
	end

	-- Six studs ahead of the camera keeps the saved point out of geometry.
	waypoints[name] = camera.CFrame * CFrame.new(0, 0, -6)
	return true, name
end

function Teleport.deleteWaypoint(name)
	if not waypoints[name] then
		return false, "unknown waypoint"
	end
	waypoints[name] = nil
	return true
end

function Teleport.waypointNames()
	local names = {}
	for name in pairs(waypoints) do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

function Teleport.toWaypoint(name)
	local target = waypoints[name]
	if not target then
		return false, "unknown waypoint"
	end

	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(target)
	return true
end

function Teleport.playerNames()
	local names = {}
	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= Players.LocalPlayer then
			table.insert(names, player.Name)
		end
	end
	table.sort(names)
	return names
end

function Teleport.toPlayer(name)
	local target = Players:FindFirstChild(name)
	if not target then
		return false, "player left"
	end

	local targetRoot = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
	if not targetRoot then
		return false, "target has no character"
	end

	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(CFrame.new(targetRoot.Position + Vector3.new(0, 3, 0)))
	return true
end

function Teleport.toPosition(vector)
	if typeof(vector) ~= "Vector3" then
		return false, "not a Vector3"
	end
	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(CFrame.new(vector))
	return true
end

return Teleport
end
__modules["features/misc"] = function()
-- misc.lua — lighting, idle guard, server actions.
local Lighting = game:GetService("Lighting")
local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local VirtualUser = game:GetService("VirtualUser")

local Misc = {}

local originals
local idleConn

function Misc.setFullbright(enabled)
	if enabled then
		if originals then
			return true
		end
		originals = {
			Ambient = Lighting.Ambient,
			OutdoorAmbient = Lighting.OutdoorAmbient,
			Brightness = Lighting.Brightness,
			ClockTime = Lighting.ClockTime,
			FogEnd = Lighting.FogEnd,
			GlobalShadows = Lighting.GlobalShadows,
		}
		Lighting.Ambient = Color3.fromRGB(200, 200, 200)
		Lighting.OutdoorAmbient = Color3.fromRGB(200, 200, 200)
		Lighting.Brightness = 3
		Lighting.ClockTime = 14
		Lighting.FogEnd = 1e6
		Lighting.GlobalShadows = false
		return true
	end

	if not originals then
		return true
	end
	for key, value in pairs(originals) do
		Lighting[key] = value
	end
	originals = nil
	return true
end

function Misc.setAntiAFK(enabled)
	if not enabled then
		if idleConn then
			idleConn:Disconnect()
			idleConn = nil
		end
		return true
	end

	if idleConn then
		return true
	end
	idleConn = Players.LocalPlayer.Idled:Connect(function()
		-- The 20-minute idle kick fires from the client; feed it a click.
		VirtualUser:CaptureController()
		VirtualUser:ClickButton2(Vector2.zero)
	end)
	return true
end

function Misc.rejoin()
	TeleportService:Teleport(game.PlaceId, Players.LocalPlayer)
	return true
end

function Misc.destroy()
	Misc.setFullbright(false)
	Misc.setAntiAFK(false)
end

return Misc
end
__modules["ui"] = function()
-- ui.lua — Rayfield window. Requires the feature modules before it runs.
local Config = __require("config")
local Util = __require("util")
local Player = __require("features/player")
local ESP = __require("features/esp")
local Teleport = __require("features/teleport")
local Misc = __require("features/misc")

local UI = {}

local RAYFIELD_URL = "https://sirius.menu/rayfield"

local Rayfield
local window
local elements = {}
local loaded = false

local function notify(title, content)
	if loaded and Rayfield then
		pcall(function()
			Rayfield:Notify({ Title = title, Content = content, Duration = 4 })
		end)
	else
		Util.notify(title, content)
	end
end

local function report(result, okMessage)
	local ok, message = result
	if ok then
		if okMessage then
			notify("Success", message or okMessage)
		end
		return true
	end
	notify("Failed", tostring(message or "unknown error"))
	return false
end

local function loadRayfield()
	local loader = loadstring(game:HttpGet(RAYFIELD_URL))
	if type(loader) ~= "function" then
		error("rayfield loader did not return a function")
	end
	return loader()
end

local function buildPlayerTab(Rayfield, tab)
	tab:CreateSection("Movement")

	elements.WalkSpeed = tab:CreateSlider({
		Name = "Walk Speed",
		Range = { 8, 300 },
		Increment = 1,
		Suffix = "studs/s",
		CurrentValue = Config.get("WalkSpeed"),
		Flag = "WalkSpeed",
		Callback = function(value)
			Player.setWalkSpeed(value)
		end,
	})

	elements.JumpPower = tab:CreateSlider({
		Name = "Jump Power",
		Range = { 50, 500 },
		Increment = 1,
		Suffix = "power",
		CurrentValue = Config.get("JumpPower"),
		Flag = "JumpPower",
		Callback = function(value)
			Player.setJumpPower(value)
		end,
	})

	tab:CreateSection("Flight")

	elements.Fly = tab:CreateToggle({
		Name = "Fly (WASD + Space/Ctrl)",
		CurrentValue = Config.get("Fly"),
		Flag = "Fly",
		Callback = function(value)
			Config.set("Fly", value)
			local ok, message = Player.setFly(value)
			if not ok then
				notify("Fly", tostring(message))
			end
		end,
	})

	elements.FlySpeed = tab:CreateSlider({
		Name = "Fly Speed",
		Range = { 10, 300 },
		Increment = 1,
		Suffix = "studs/s",
		CurrentValue = Config.get("FlySpeed"),
		Flag = "FlySpeed",
		Callback = function(value)
			Config.set("FlySpeed", value)
		end,
	})

	tab:CreateSection("Collision")

	elements.NoClip = tab:CreateToggle({
		Name = "NoClip",
		CurrentValue = Config.get("NoClip"),
		Flag = "NoClip",
		Callback = function(value)
			Config.set("NoClip", value)
			Player.setNoClip(value)
		end,
	})

	elements.InfiniteJump = tab:CreateToggle({
		Name = "Infinite Jump",
		CurrentValue = Config.get("InfiniteJump"),
		Flag = "InfiniteJump",
		Callback = function(value)
			Config.set("InfiniteJump", value)
			Player.setInfiniteJump(value)
		end,
	})

	tab:CreateButton({
		Name = "Reset Character",
		Callback = function()
			report(Player.resetCharacter(), "character reset")
		end,
	})
end

local function buildVisualsTab(Rayfield, tab)
	tab:CreateSection("Players")

	elements.ESP = tab:CreateToggle({
		Name = "Player ESP",
		CurrentValue = Config.get("ESP"),
		Flag = "ESP",
		Callback = function(value)
			Config.set("ESP", value)
			ESP.setEnabled(value)
		end,
	})

	elements.ESPColor = tab:CreateColorPicker({
		Name = "ESP Color",
		Color = Color3.fromRGB(120, 180, 255),
		Flag = "ESPColor",
		Callback = function(color)
			ESP.setColor(color)
		end,
	})

	tab:CreateSection("Lighting")

	elements.Fullbright = tab:CreateToggle({
		Name = "Fullbright",
		CurrentValue = Config.get("Fullbright"),
		Flag = "Fullbright",
		Callback = function(value)
			Config.set("Fullbright", value)
			Misc.setFullbright(value)
		end,
	})
end

local function buildTeleportTab(Rayfield, tab)
	tab:CreateSection("Waypoints")

	elements.WaypointName = tab:CreateInput({
		Name = "Waypoint Name",
		CurrentValue = "",
		PlaceholderText = "spawn",
		RemoveTextAfterFocusLost = false,
		Flag = "WaypointName",
		Callback = function()
		end,
	})

	tab:CreateButton({
		Name = "Save Waypoint Here",
		Callback = function()
			local name = elements.WaypointName and elements.WaypointName.CurrentValue or ""
			local ok, result = Teleport.saveWaypoint(name)
			if ok then
				local names = Teleport.waypointNames()
				if elements.Waypoints then
					elements.Waypoints:Refresh((#names > 0) and names or { "(empty)" })
				end
				notify("Waypoint", ("saved \"%s\""):format(result))
			else
				notify("Waypoint", tostring(result))
			end
		end,
	})

	local waypointNames = Teleport.waypointNames()
	elements.Waypoints = tab:CreateDropdown({
		Name = "Saved Waypoints",
		Options = (#waypointNames > 0) and waypointNames or { "(empty)" },
		CurrentOption = {},
		MultipleOptions = false,
		Flag = "Waypoints",
		Callback = function()
		end,
	})

	tab:CreateButton({
		Name = "Teleport To Waypoint",
		Callback = function()
			local selected = elements.Waypoints and elements.Waypoints.CurrentOption or {}
			local name = selected[1]
			if not name or name == "(empty)" then
				notify("Teleport", "pick a waypoint first")
				return
			end
			report(Teleport.toWaypoint(name))
		end,
	})

	tab:CreateSection("Players")

	local playerNames = Teleport.playerNames()
	elements.Players = tab:CreateDropdown({
		Name = "Player",
		Options = (#playerNames > 0) and playerNames or { "(empty)" },
		CurrentOption = {},
		MultipleOptions = false,
		Flag = "Players",
		Callback = function()
		end,
	})

	tab:CreateButton({
		Name = "Teleport To Player",
		Callback = function()
			local selected = elements.Players and elements.Players.CurrentOption or {}
			local name = selected[1]
			if not name or name == "(empty)" then
				notify("Teleport", "pick a player first")
				return
			end
			report(Teleport.toPlayer(name))
		end,
	})

	tab:CreateButton({
		Name = "Refresh Player List",
		Callback = function()
			local names = Teleport.playerNames()
			if elements.Players then
				elements.Players:Refresh(names)
			end
			notify("Players", ("%d in server"):format(#names))
		end,
	})
end

local function buildMiscTab(Rayfield, tab)
	tab:CreateSection("Session")

	elements.AntiAFK = tab:CreateToggle({
		Name = "Anti-AFK",
		CurrentValue = Config.get("AntiAFK"),
		Flag = "AntiAFK",
		Callback = function(value)
			Config.set("AntiAFK", value)
			Misc.setAntiAFK(value)
		end,
	})

	tab:CreateButton({
		Name = "Rejoin Server",
		Callback = function()
			notify("Rejoin", "teleporting")
			task.wait(0.6)
			Misc.rejoin()
		end,
	})

	tab:CreateSection("Diagnostics")

	tab:CreateButton({
		Name = "Test Notification",
		Callback = function()
			notify("Test", "notification pipeline is live")
		end,
	})

	tab:CreateButton({
		Name = "Destroy UI",
		Callback = function()
			UI.destroy()
		end,
	})
end

local function buildConfigTab(Rayfield, tab)
	tab:CreateButton({
		Name = "Save Settings",
		Callback = function()
			notify("Config", select(2, Config.save()) or "saved")
		end,
	})

	tab:CreateButton({
		Name = "Load Settings",
		Callback = function()
			local ok, message = Config.load()
			notify("Config", tostring(message))
			if ok then
				UI.sync()
			end
		end,
	})
end

-- Push the current config into live features and into the UI elements.
function UI.sync()
	if elements.WalkSpeed then
		elements.WalkSpeed:Set(Config.get("WalkSpeed"))
	end
	if elements.JumpPower then
		elements.JumpPower:Set(Config.get("JumpPower"))
	end
	if elements.FlySpeed then
		elements.FlySpeed:Set(Config.get("FlySpeed"))
	end

	Player.setWalkSpeed(Config.get("WalkSpeed"))
	Player.setJumpPower(Config.get("JumpPower"))

	if Config.get("Fly") then
		Player.setFly(true)
	else
		Player.setFly(false)
	end
	if elements.Fly then
		elements.Fly:Set(Config.get("Fly"))
	end

	Player.setNoClip(Config.get("NoClip"))
	if elements.NoClip then
		elements.NoClip:Set(Config.get("NoClip"))
	end

	Player.setInfiniteJump(Config.get("InfiniteJump"))
	if elements.InfiniteJump then
		elements.InfiniteJump:Set(Config.get("InfiniteJump"))
	end

	ESP.setEnabled(Config.get("ESP"))
	if elements.ESP then
		elements.ESP:Set(Config.get("ESP"))
	end

	Misc.setFullbright(Config.get("Fullbright"))
	if elements.Fullbright then
		elements.Fullbright:Set(Config.get("Fullbright"))
	end

	Misc.setAntiAFK(Config.get("AntiAFK"))
	if elements.AntiAFK then
		elements.AntiAFK:Set(Config.get("AntiAFK"))
	end
end

function UI.build()
	if window then
		return window
	end

	local Rayfield = loadRayfield()
	loaded = true

	Util.setNotifier(function(title, content)
		notify(title, content)
	end)

	window = Rayfield:CreateWindow({
		Name = "OJB Test Hub",
		Icon = 0,
		LoadingTitle = "OJB Test Hub",
		LoadingSubtitle = "loadstring test build",
		Theme = "Default",
		ToggleUIKeybind = "K",
		DisableRayfieldPrompts = true,
	})

	buildPlayerTab(Rayfield, window:CreateTab("Player", "user"))
	buildVisualsTab(Rayfield, window:CreateTab("Visuals", "eye"))
	buildTeleportTab(Rayfield, window:CreateTab("Teleport", "map-pin"))
	buildMiscTab(Rayfield, window:CreateTab("Misc", "wrench"))
	buildConfigTab(Rayfield, window:CreateTab("Config", "save"))

	UI.sync()
	notify("OJB Test Hub", "loaded — press K to toggle")
	return window
end

function UI.destroy()
	pcall(function()
		Player.destroy()
		ESP.destroy()
		Misc.destroy()
	end)
	if window then
		pcall(function()
			window:Destroy()
		end)
		window = nil
	end
	elements = {}
	loaded = false
	Util.notify("OJB Test Hub", "unloaded")
end

return UI
end
__modules["init"] = function()
-- init.lua — entry point. Runs once after every module is registered.
local Util = __require("util")
local Player = __require("features/player")
local ESP = __require("features/esp")
local UI = __require("ui")

local VERSION = "0.1.0"

local function main()
	-- Re-executing the loadstring must replace the running instance, not stack one.
	local previous = _G.OJB_TestHub
	if previous and type(previous.destroy) == "function" then
		pcall(previous.destroy)
	end

	Player.bind()
	ESP.bind()

	local ok, err = pcall(UI.build)
	if not ok then
		Util.notify("OJB Test Hub", "failed to build UI: " .. tostring(err))
		error(err)
	end

	local handle = {
		version = VERSION,
		destroy = function()
			UI.destroy()
			Player.destroy()
			ESP.destroy()
			if _G.OJB_TestHub == handle then
				_G.OJB_TestHub = nil
			end
		end,
	}

	_G.OJB_TestHub = handle
	return handle
end

return main()
end
return __require("init")
